syntax:
column "web servers" {
  w1: web-01
  w2: web-02
}

direction down
row {
  lb: Load balancer
  rp: Reverse proxy
}

column {
  row {
    frame a "edge" { ... }
    frame b "DMZ" { ... }
  }
  row {
    frame c "app" { ... }
  }
}

rail logs "management" [right] {
  siem: SIEM
}
fw1 -> logs

table orders "Orders" {
  id uuid pk
  customer_id uuid fk
}
orders.customer_id -> customers.id [n-1]
